    rows = len(input_grid)
    cols = len(input_grid[0])
    output = [[v for v in row] for row in input_grid]

    for r in range(rows):
        is_full_row = all(input_grid[r][c] == 9 for c in range(cols))

        if is_full_row:
            for c in range(cols):
                output[r][c] = 2
            continue

        for c in range(cols):
            if output[r][c] == 9:
                if c > 0 and input_grid[r][c-1] == 9:
                    # Has left 9, so stays 9 (RIGHT of pair)
                    pass
                else:
