# Let me properly transform the test input and print each row's result

def transform(grid, background):
    rows = len(grid)
    cols = len(grid[0])
    output = [[grid[r][c] for c in range(cols)] for r in range(rows)]

    for r in range(rows):
        # Check if this is a full row of 9s or 9s and background
        is_full = all(grid[r][c] == 9 for c in range(cols)) or (all(grid[r][c] in [9, background] for c in range(cols)) and all(output[r][c] == 9 for c in range(cols)))

        if is_full and all(grid[r][c] == 9 for c in range(cols)):
            for c in range(cols):
                output[r][c] = 2
            continue

        for c in range(cols):
            if output[r][c] == 9:
                if c > 0 and output[r][c-1] == 9:
                    # Has left 9, stays 9
                    pass
                else:
                    # No left 9, becomes 2
                    output[r][c] = 2

    return output

# Transform test input (background=5)
