# Let me try a new rule that handles full columns too:
# Rule 1: Full ROW of 9s → all 2s
# Rule 2: Full COLUMN of 9s → all 2s
# Rule 3: Left 9 of pair → 2, right 9 → 9
# Rule 4: Isolated 9 → 2

def transform_with_full_columns(grid):
    rows = len(grid)
    cols = len(grid[0])
    output = [[grid[r][c] for c in range(cols)] for r in range(rows)]

    # First, mark which cells are in full columns
    full_col_mask = [[False for _ in range(cols)] for _ in range(rows)]
    for c in range(cols):
        if all(grid[r][c] == 9 for r in range(rows)):
            for r in range(rows):
                full_col_mask[r][c] = True

    # Now apply transformations
    for r in range(rows):
        # Full row of 9s → all 2s
        if all(output[r][c] == 9 for c in range(cols)):
            for c in range(cols):
                output[r][c] = 2
            continue

        for c in range(cols):
            if output[r][c] == 9:
                # If in full column, become 2
                if full_col_mask[r][c]:
                    output[r][c] = 2
                elif c > 0 and grid[r][c-1] == 9:
                    # Left 9 check, stay 9 as right 9
                    pass
                else:
                    # No left 9 or not in full column, become 2
                    output[r][c] = 2

    return output

