def transform_all_fulls(grid):
    rows = len(grid)
    cols = len(grid[0])
    output = [[grid[r][c] for c in range(cols)] for r in range(rows)]

    # Mark full columns
    full_col_mask = [[False for _ in range(cols)] for _ in range(rows)]
    for c in range(cols):
        is_full_col = all(grid[r][c] == 9 for r in range(rows))
        if is_full_col:
            for r in range(rows):
                full_col_mask[r][c] = True

    for r in range(rows):
        # Full row → all 2s
        if all(output[r][c] == 9 for c in range(cols)):
            for c in range(cols):
                output[r][c] = 2
            continue

        for c in range(cols):
            if output[r][c] == 9:
                if full_col_mask[r][c]:
                    output[r][c] = 2  # Full column, all 2s
                elif c > 0 and grid[r][c-1] == 9:
                    pass  # Left 9, right 9
                else:
                    output[r][c] = 2  # Isolated or left 9

    return output

